// Model-loader test pack (P8 pipeline). Two DEV hulls — one warship, one industrial ship — drawn from
// external GLB fixtures (public/assets/content/models/fixtures/). Dev hulls are never sold, built or
// granted (no sale, no blueprint): only tests and the model preview (?modelview=…) spawn them.
// The fixture files are generated by scripts/models/make-fixtures.ts and are NOT final game art.
//
// This pack is also the reference for adding a ship with its own model: hull data + variant + preset
// + asset entry — no renderer or combat code changes (docs/CODEX_CONTENT_GUIDE.md §26–§31).
import type { AssetDef, ContentPack, HardpointDef, HullDef, PresetDef, VariantDef } from '../../schema';

